package dev.pocketengine.features.local.runtime;

import static org.junit.Assert.*;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import org.json.JSONObject;
import org.junit.Test;

public final class RuntimePtyInputTest {
    private JSONObject text(String value)throws Exception{return new JSONObject().put("action","text").put("text",value);}
    @Test public void originalInputHasOneImmutablePacketAndAckContainsNoText()throws Exception{RuntimePtyInput input=new RuntimePtyInput(100);RuntimePtyInput.Ticket ticket=input.offer("input_1",text("hello\n"));ByteBuffer packet=ByteBuffer.wrap(input.next()).order(ByteOrder.BIG_ENDIAN);assertEquals(RuntimePtyInput.TEXT,packet.getInt());assertEquals(ticket.sequence,packet.getLong());packet.getInt();packet.getInt();assertEquals(6,packet.getInt());byte[] value=new byte[packet.remaining()];packet.get(value);assertArrayEquals("hello\n".getBytes(java.nio.charset.StandardCharsets.UTF_8),value);assertNull(input.next());JSONObject observed=input.observed(ticket.sequence,6,0,0,0,true);assertEquals("delivered",observed.getString("status"));assertFalse(observed.toString().contains("hello"));assertSame(ticket,input.offer("input_1",text("hello\n")));assertNull(input.next());assertThrows(SecurityException.class,()->input.offer("input_1",text("changed")));}
    @Test public void exactBudgetQueueTimeoutAndCloseDoNotGuessDelivery()throws Exception{RuntimePtyInput input=new RuntimePtyInput(3);RuntimePtyInput.Ticket ticket=input.offer("input_1",text("abc"));assertThrows(SecurityException.class,()->input.offer("input_2",text("a")));assertEquals("not_dispatched",input.await(ticket,null,0).getString("status"));assertNull(input.next());assertEquals(3,input.await(ticket,null,0).getInt("inputBytesCharged"));input.closed();assertThrows(SecurityException.class,()->input.offer("input_2",text("a")));}
    @Test public void dequeuedTimeoutIsUnknownAndOnlyRealLateAckCanResolveIt()throws Exception{RuntimePtyInput input=new RuntimePtyInput(100);RuntimePtyInput.Ticket ticket=input.offer("input_1",text("a"));assertNotNull(input.next());assertEquals("unknown",input.await(ticket,null,0).getString("status"));assertThrows(SecurityException.class,()->input.offer("input_2",text("b")));assertEquals("delivered",input.observed(ticket.sequence,1,0,0,0,true).getString("status"));assertEquals("delivered",input.await(ticket,null,0).getString("status"));assertNull(input.next());assertThrows(IllegalStateException.class,()->input.observed(ticket.sequence,1,0,0,0,true));}
    @Test public void partialWriteIsNotRetriedOrPromotedToComplete()throws Exception{RuntimePtyInput input=new RuntimePtyInput(100);RuntimePtyInput.Ticket ticket=input.offer("input_1",text("abc"));input.next();JSONObject actual=input.observed(ticket.sequence,1,5,0,0,true);assertEquals("unknown",actual.getString("status"));assertEquals(1,actual.getInt("writtenBytes"));assertSame(ticket,input.offer("input_1",text("abc")));assertNull(input.next());assertThrows(SecurityException.class,()->input.offer("input_2",text("def")));}
    @Test public void resizeNeedsNativeReadbackAndFailedEffectIsUnknown()throws Exception{RuntimePtyInput input=new RuntimePtyInput(100);RuntimePtyInput.Ticket ticket=input.offer("resize_1",new JSONObject().put("action","resize").put("rows",30).put("columns",100));input.next();assertEquals("unknown",input.observed(ticket.sequence,0,5,0,0,true).getString("status"));RuntimePtyInput second=new RuntimePtyInput(100);RuntimePtyInput.Ticket resized=second.offer("resize_2",new JSONObject().put("action","resize").put("rows",30).put("columns",100));second.next();assertEquals("delivered",second.observed(resized.sequence,0,0,30,100,true).getString("status"));}
    @Test public void eofChargesOneControlByteAndRawModeRejectionDoesNotPretendClosed()throws Exception{RuntimePtyInput input=new RuntimePtyInput(1);RuntimePtyInput.Ticket ticket=input.offer("eof_1",new JSONObject().put("action","eof"));input.next();JSONObject denied=input.observed(ticket.sequence,0,95,0,0,false);assertEquals("not_dispatched",denied.getString("status"));assertFalse(denied.has("stdinClosed"));assertThrows(SecurityException.class,()->input.offer("input_2",text("a")));}
    @Test public void invalidCompoundOrOversizedInputIsRejectedBeforeQueueing()throws Exception{RuntimePtyInput input=new RuntimePtyInput(10000);assertThrows(IllegalArgumentException.class,()->input.offer("input_1",text("x").put("rows",10)));assertThrows(IllegalArgumentException.class,()->input.offer("input_2",text("x".repeat(4097))));assertThrows(IllegalArgumentException.class,()->input.offer("resize_1",new JSONObject().put("action","resize")));assertThrows(IllegalArgumentException.class,()->input.offer("eof_1",new JSONObject().put("action","eof").put("text","a")));assertNull(input.next());}
}
